const NAME_TOKEN = /^[\p{L}][\p{L}'\-.]{0,30}$/u;
const MAX_PROMPT_NAMES = 30;
function safeNameForPrompt(first, last) {
  const parts = [first, last].filter(Boolean).map((p) => String(p).trim()).filter(Boolean);
  if (parts.length === 0 || parts.length > 2) return null;
  if (!parts.every((p) => NAME_TOKEN.test(p))) return null;
  return parts.join(' ');
}
const candidates = $json.candidates || [];
const names = candidates.map((c) => safeNameForPrompt(c.firstName, c.lastName)).filter(Boolean).slice(0, MAX_PROMPT_NAMES);
const prompt = names.length === 0 ? null : 'Contacts at this event: ' + names.join(', ') + '.';
return [{ json: { prompt: prompt } }];

const TERMINAL_ERROR_PATTERNS = [/no legible business card detected/i, /refusing to (build a prompt|upload)/i];
const message = $json.error || 'unknown error';
const errorClass = TERMINAL_ERROR_PATTERNS.some((re) => re.test(message)) ? 'terminal' : 'transient';
return [{ json: { errorMessage: message, errorClass: errorClass } }];
